<script setup>import { computed } from 'vue'; import { useRoute } from 'vue-router'; import PageHero from '../components/PageHero.vue'; import { findRecord } from '../data/contentLookup'; import { people } from '../data/people'; const route=useRoute(); const person=computed(()=>findRecord(people,route.params.id))</script>
<template><PageHero :title="person ? person.name : '人物内容不存在'" description="历史人物详情" :image="person?.image" /><section class="section"><div class="shell"><div v-if="person" class="detail-layout"><article class="detail-main"><img :src="person.image" :alt="person.name" /><p class="eyebrow">人物档案 · 演示</p><h2>人物简介</h2><p>{{ person.summary }}</p><h3>生平与相关经历</h3><p>{{ person.bio }}</p></article><aside class="detail-aside"><h3>关联资料</h3><p>相关历史事件：待核实</p><p>相关馆藏文物：待核实</p><RouterLink class="text-link" to="/people">返回人物列表 →</RouterLink></aside></div><div v-else class="empty-state"><h2>内容不存在</h2><RouterLink class="button" to="/people">返回人物列表</RouterLink></div></div></section></template>
